Definition pad_postZ (ra : word) (q : Z) (gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (Fp : Z) (fl0 : byte) (j1 j2 : list byte) (lbfw : word) (B : Z) (content junk : list byte) (canary : word)
    (C n : Z) (m : word -> option byte) : machine_state -> Prop := ltac2:(Rpl.RP.run_i (rplG ()) 30 "S>0!1,1|600;!1+00|21;|500;|30;!1,14!1+05!1+I6%~R1!1+26!2+N+=+=!2'H#^1!1,K|;228;!2'^T#H!1'_B!2'_G6#G|508;!1'^X#C$ra;R1$q;R+=$gp;R1$tp;R1$s0;R1$s1;R1$s2;R1$s3;R1$s4;R1$s5;R1$s6;R1$s7;R1$s8;R1$s9;R1$s10;R1$s11;R1$F;R!2'^L!1,121$fc;R!1+0!1,13$Fp;R+=$fl0;R6$j1;R7$j2;R7$lbfw;R1$B;R+=$content;R7$junk;R7$canary;R1$C;R+=$n;R+=$m;R8$ms';R+^M!2+^N1$t0;R1!2+^N1$t1;R1!2+^N1$t2;R1!2+^N1$a0;R1!2+^N1$a1;R1!2+^N1$a2;R1!2+^N1$a3;R1!2+^N1$a4;R1!2+^N1$a5;R1!2+^N1$a6;R1!2+^N1$a7;R1!2+^N1$t3;R1!2+^N1$t4;R1!2+^N1$t5;R1!2+^N1$t6;R1!2+^N8$m';R8!2+3!3+L+^M#A!7'^O!O'^P#^2!2':0#^1#^0#\#@#?#>#[#Z#=#<#;#:#9#8#7#6#Y#X#W#V#U#T#S#R#Q#P#5#4#3#2#O!1'^Q#^2#N!1,T1#1!1'^R'5!2+3!3'^S!3,79!4,Q+=+=:#^1!3,79!4,Q+=+=;!2'^T;#C!3,79!4,Q+=+=!2'^T#M!1,K<!2'^T#M!1,K|510;!1,<9#B#1!2+3!3'^U'5#B#1!2+3!2'^V'5#1!2+3!4'_H'5#1:#^1!2+3!9'_I#1#M#L#K#J#I#H!3'U6#G!3'^Y6!2':5#D=!3'_J6=#F!2'_K#1#E").

Lemma pad_call : forall ra gp tp t0 t1 t2 s0 s1 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : word -> option byte) (q Fp C W L FL : Z)
    (fl0 : byte) (j1 j2 : list byte) (lbfw : word) (B : Z) (content junk : list byte) (canary : word),
  wfile m Fp fl0 j1 j2 lbfw B content junk ->
  ssp_cells m canary ->
  stk rsegs m (q - 2600) q ->
  mem_inv rsegs m ->
  (0 <= C < 256)%Z -> (-2^31 <= W < 2^31)%Z -> (0 <= L < 2^31)%Z -> (0 <= FL < 2^32)%Z ->
  (W - L < 256)%Z ->
  (pad_n W L FL <= Z.of_nat (length junk))%Z ->
  (ssp_guard + 8 <= q - 2600)%Z -> (q < 2^64)%Z ->
  (q <= Fp < 2^64)%Z -> (q <= B)%Z ->

  aenv m -> zsh m (q - 2600) q ->
  zsh m B (B + Z.of_nat (length content) + Z.of_nat (length junk)) ->
  (0x10007fff8000 + 2600 <= q <= 0x7fffffffff00)%Z ->
  (B + Z.of_nat (length content) + Z.of_nat (length junk) <= 0x7fffffffff00)%Z -> (Fp + 148 <= 0x7fffffffff00)%Z ->
  evt rsegs (pad_postZ ra q gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc
               Fp fl0 j1 j2 lbfw B content junk canary C (pad_n W L FL) m)
